/**
 * @summary Receive GitHub Actions test results
 */
export const getGithubWebhookUrl = () => {
  return `/api/webhooks/github`;
};

export const githubWebhook = async (
  gitHubWebhookPayload: GitHubWebhookPayload,
  options?: RequestInit,
): Promise<WebhookResponse> => {
  return customFetch<WebhookResponse>(getGithubWebhookUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(gitHubWebhookPayload),
  });
};

export const getGithubWebhookMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof githubWebhook>>,
    TError,
    { data: BodyType<GitHubWebhookPayload> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof githubWebhook>>,
  TError,
  { data: BodyType<GitHubWebhookPayload> },
  TContext
> => {
  const mutationKey = ["githubWebhook"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof githubWebhook>>,
    { data: BodyType<GitHubWebhookPayload> }
  > = (props) => {
    const { data } = props ?? {};

    return githubWebhook(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type GithubWebhookMutationResult = NonNullable<
  Awaited<ReturnType<typeof githubWebhook>>
>;
export type GithubWebhookMutationBody = BodyType<GitHubWebhookPayload>;
export type GithubWebhookMutationError = ErrorType<unknown>;

/**
 * @summary Receive GitHub Actions test results
 */
export const useGithubWebhook = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof githubWebhook>>,
    TError,
    { data: BodyType<GitHubWebhookPayload> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof githubWebhook>>,
  TError,
  { data: BodyType<GitHubWebhookPayload> },
  TContext
> => {
  return useMutation(getGithubWebhookMutationOptions(options));
};
